head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[common > E > onmouseover]<br/>컴포넌트 영역 또는 자식 요소 영역 내로 마우스 포인터가 들어 왔을 때 발생합니다.",
    "validation" : [
        "컴포넌트 영역 내로 마우스 포인터가 들어 왔을 때 발생합니다.",
        "컴포넌트 자식 영역 내로 마우스 포인터가 들어 왔을 때 발생합니다.",
        "자식 컴포넌트에서 onmouseover 이벤트가 발생하면 Group 컴포넌트로 버블링됩니다.",
        "Group 컴포넌트 영역으로 들어올 땐 onmouseover 이벤트가 발생한 후 onmouseenter 이벤트가 발생합니다.",
    ]
} 


scwin.wf_sample_onwframeload = function () {
    let wf_body_left = wf_sample.getObj("wf_body_left");
    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



scwin.onpageload = function () {
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    // comp 생성 함수 호출    
    let eList = $c.gcm.createEList(["onmouseover", "onmouseenter"])

    // comp 생성 함수 호출    
    $c.gcm.createBasicGroup('', eList);    
}
